const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8');
    const tokens = input.trim().split(/\s+/);
    if (tokens.length === 0 || tokens[0] === "") return;

    let ptr = 0;
    const L = parseInt(tokens[ptr++], 10);
    const C = parseInt(tokens[ptr++], 10);

    const grid = [];
    const rowSums = new Int32Array(L);

    const allVarsSet = new Set();

    for (let i = 0; i < L; i++) {
        const row = [];
        for (let j = 0; j < C; j++) {
            const v = tokens[ptr++];
            row.push(v);
            allVarsSet.add(v);
        }
        rowSums[i] = parseInt(tokens[ptr++], 10);
        grid.push(row);
    }

    const colSums = new Int32Array(C);
    for (let j = 0; j < C; j++) {
        colSums[j] = parseInt(tokens[ptr++], 10);
    }

    // Prepare equations
    // Each equation will have a list of variables and a target sum.
    const equations = [];

    // Rows
    for (let i = 0; i < L; i++) {
        equations.push({
            vars: grid[i],
            sum: rowSums[i]
        });
    }

    // Columns
    for (let j = 0; j < C; j++) {
        const colVars = [];
        for (let i = 0; i < L; i++) {
            colVars.push(grid[i][j]);
        }
        equations.push({
            vars: colVars,
            sum: colSums[j]
        });
    }

    const knownVals = new Map();
    const totalVars = allVarsSet.size;

    while (knownVals.size < totalVars) {
        let progressed = false;

        for (const eq of equations) {
            let unknownVar = null;
            let unknownCount = 0;
            let knownSum = 0;
            let hasMultipleUnknowns = false;

            for (const v of eq.vars) {
                if (knownVals.has(v)) {
                    knownSum += knownVals.get(v);
                } else {
                    if (unknownVar === null) {
                        unknownVar = v;
                        unknownCount = 1;
                    } else if (unknownVar === v) {
                        unknownCount++;
                    } else {
                        hasMultipleUnknowns = true;
                        break;
                    }
                }
            }

            if (!hasMultipleUnknowns && unknownVar !== null) {
                const val = (eq.sum - knownSum) / unknownCount;
                knownVals.set(unknownVar, Math.round(val));
                progressed = true;
                break;
            }
        }

        if (!progressed) {
            break;
        }
    }

    const sortedVars = Array.from(knownVals.keys()).sort();
    let output = '';
    for (const v of sortedVars) {
        output += `${v} ${knownVals.get(v)}\n`;
    }
    process.stdout.write(output);
}

solve();
